'use strict';
let currentSubject='history',activeQuestions=QUIZ_DATA.history,CORE=activeQuestions.filter(q=>!q.extra),CHAPTERS=QUIZ_CHAPTERS.history;
let progressRoot=QuizStore.migrate(),saved=progressRoot.history;
let view='catalog',goal=8,chapter=0,topic='',query='',onlyReview=false,includeExtra=false,bankOrigin='all',page=1,mode='learn',size=20,order='shuffle',examMinutes=20,session=null,result=null,resultFilter='wrong',storageWarned=false,audioContext=null,speakingKey=null,timerHandle=null;
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const HIGHLIGHT_PATTERNS=[
  /\b(?:18|19|20)\d{2}(?:\s*[–—-]\s*(?:18|19|20)\d{2})?\b/g,
  /“[^”]{2,90}”|"[^"]{2,90}"/g,
  /(?:không đúng|không thuộc|không phải|chưa đúng|chủ yếu|cơ bản|quan trọng nhất|quyết định nhất|trực tiếp|đầu tiên|lần đầu tiên|hoàn toàn|bức thiết nhất|tiêu biểu nhất|lớn nhất)/gi,
  /(?:Nguyễn Ái Quốc|Hồ Chí Minh|Trần Phú|Lê Duẩn|Võ Nguyên Giáp|Phan Bội Châu|Phan Châu Trinh)/gi,
  /(?:Đảng Cộng sản Việt Nam|Đảng Cộng sản Đông Dương|Đông Dương Cộng sản Đảng|An Nam Cộng sản Đảng|Đông Dương Cộng sản liên đoàn|Hội Việt Nam Cách mạng Thanh niên|Việt Nam Quốc dân Đảng|Quốc tế Cộng sản|Mặt trận Việt Minh|Mặt trận Dân tộc Giải phóng miền Nam Việt Nam)/gi,
  /(?:Cương lĩnh chính trị|Luận cương chính trị|Chính cương vắn tắt|Sách lược vắn tắt|Tuyên ngôn Độc lập|Lời kêu gọi toàn quốc kháng chiến|Đường Kách mệnh|Bản án chế độ thực dân Pháp)/gi,
  /(?:Cách mạng tháng Tám|Xô viết Nghệ Tĩnh|Điện Biên Phủ|Đồng Khởi|Mậu Thân|Chiến dịch Hồ Chí Minh|đổi mới|công nghiệp hóa|hiện đại hóa|thực dân Pháp|đế quốc Mỹ|phát xít Nhật)/gi,
  /(?:giai cấp công nhân|giai cấp nông dân|giai cấp tư sản|giai cấp tiểu tư sản|địa chủ phong kiến)/gi
];
function highlightText(value){const text=String(value),matches=[];for(const pattern of HIGHLIGHT_PATTERNS){pattern.lastIndex=0;let m;while((m=pattern.exec(text))){matches.push({start:m.index,end:m.index+m[0].length});if(!m[0].length)pattern.lastIndex++;}}matches.sort((a,b)=>a.start-b.start||b.end-a.end);const picked=[];for(const match of matches){if(picked.length>=6)break;if(!picked.some(x=>match.start<x.end&&match.end>x.start))picked.push(match);}picked.sort((a,b)=>a.start-b.start);if(!picked.length)return esc(text);let html='',cursor=0;for(const match of picked){html+=esc(text.slice(cursor,match.start))+`<mark class="key-highlight">${esc(text.slice(match.start,match.end))}</mark>`;cursor=match.end;}return html+esc(text.slice(cursor));}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500);}
function playInteraction(kind='neutral'){if(!saved.prefs.sound)return;const AudioCtor=window.AudioContext||window.webkitAudioContext;if(!AudioCtor)return;try{audioContext||=new AudioCtor();if(audioContext.state==='suspended')audioContext.resume();const now=audioContext.currentTime,notes=kind==='correct'?[523.25,659.25]:kind==='wrong'?[329.63,246.94]:[440];notes.forEach((frequency,i)=>{const start=now+i*.075,osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(.33,start+.012);gain.gain.exponentialRampToValueAtTime(.0001,start+.11);osc.connect(gain);gain.connect(audioContext.destination);osc.start(start);osc.stop(start+.12);});}catch{}}
function speechText(q){return `Câu hỏi. ${q.question}. Các phương án. ${q.options.map((o,i)=>`${q.labels?.[i]||'ABCD'[i]}. ${o}`).join('. ')}.`;}
function setSpeechButtons(){document.querySelectorAll('[data-tts]').forEach(b=>{const active=b.dataset.tts===speakingKey;b.setAttribute('aria-pressed',String(active));b.innerHTML=active?'■ Dừng đọc':'◉ Đọc câu hỏi';});}
function cancelSpeech(){if('speechSynthesis'in window)window.speechSynthesis.cancel();speakingKey=null;setSpeechButtons();}
function speakQuestion(key){if(!('speechSynthesis'in window)){toast('Trình duyệt này chưa hỗ trợ đọc văn bản.');return;}if(speakingKey===key){cancelSpeech();return;}cancelSpeech();const q=BYKEY[key],u=new SpeechSynthesisUtterance(speechText(q));u.lang='vi-VN';u.rate=saved.prefs.speechRate;u.pitch=1;const voices=window.speechSynthesis.getVoices(),voice=voices.find(v=>v.lang.toLowerCase()==='vi-vn')||voices.find(v=>v.lang.toLowerCase().startsWith('vi'));if(voice)u.voice=voice;speakingKey=key;const done=()=>{if(speakingKey===key){speakingKey=null;setSpeechButtons();}};u.onend=done;u.onerror=e=>{done();if(!['canceled','interrupted'].includes(e.error))toast('Không phát được giọng đọc. Hãy kiểm tra giọng tiếng Việt và âm thanh trên thiết bị.');};window.speechSynthesis.speak(u);setSpeechButtons();}
function mediaControls(q){const tts='speechSynthesis'in window,rate=saved.prefs.speechRate.toFixed(1);return `<div class="media-controls"><button type="button" class="btn media-button" data-tts="${q.key}" aria-pressed="false" ${tts?'':'disabled'}>${tts?'◉ Đọc câu hỏi':'Không hỗ trợ đọc'}</button><button type="button" class="btn media-button" data-sound aria-pressed="${saved.prefs.sound}">${saved.prefs.sound?'♪ Âm thanh: Bật':'♪ Âm thanh: Tắt'}</button><label class="speech-rate">Tốc độ đọc <input type="range" data-speech-rate min="0.6" max="1.5" step="0.1" value="${rate}" ${tts?'':'disabled'}><output data-speech-rate-output>${rate}×</output></label></div>`;}
function normalize(s){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function hintBox(q){const open=!!session?.hints?.[q.key],id='hint-'+q.key.replace('.','-');return `<div class="hint-wrap"><button type="button" class="btn hint-button" data-hint="${q.key}" aria-expanded="${open}" aria-controls="${id}"><span aria-hidden="true">✦</span> ${open?'Ẩn gợi ý':'Gợi ý'}</button><div class="hint-panel" id="${id}" ${open?'':'hidden'}><strong>THỬ NGHĨ THEO HƯỚNG NÀY</strong><p>${esc(q.hint)}</p></div></div>`;}
function subjectTitle(){return SUBJECTS.find(s=>s.id===currentSubject).title;}
function subjectStats(id){const a=QUIZ_DATA[id].filter(q=>!q.extra),p=progressRoot[id];return {total:a.length,seen:a.filter(q=>p.progress[q.key]&&(p.progress[q.key].lastAnswer||!('lastAnswer'in p.progress[q.key]))).length,correct:a.filter(q=>p.progress[q.key]?.last===true).length,wrong:a.filter(q=>p.progress[q.key]?.last===false&&isGradable(q)).length,saved:p.bookmarks.filter(k=>BYKEY[k]?.subject===id).length,gradable:a.filter(isGradable).length};}
function ensurePrefs(){const rate=Number(saved.prefs?.speechRate);saved.prefs={sound:saved.prefs?.sound!==false,speechRate:rate>=.6&&rate<=1.5?rate:.9};saved._sync||={bookmarks:{}};saved._sync.bookmarks||={};}
function save(){progressRoot[currentSubject]=saved;try{QuizStore.persist(progressRoot);}catch{if(!storageWarned){storageWarned=true;toast('Không lưu được tiến độ. Hãy xuất bản sao lưu.');}}updateNav();window.KienCloud?.queue();}
function updateNav(){const s=subjectStats(currentSubject);const w=$('#wrong-count'),b=$('#saved-count');if(w)w.textContent=s.wrong;if(b)b.textContent=s.saved;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
function stopTimer(){if(timerHandle!==null)clearInterval(timerHandle);timerHandle=null;}
function remainingSeconds(){return Math.max(0,Math.ceil(((session?.deadline||0)-Date.now())/1000));}
function timerText(){const n=remainingSeconds();return Math.floor(n/60)+':'+String(n%60).padStart(2,'0');}
function tickTimer(){if(view!=='quiz'||!session||session.mode!=='exam'||!session.deadline)return;const node=$('#exam-clock');if(node)node.textContent=timerText();if(remainingSeconds()===0)finish(true);}
function armTimer(){stopTimer();if(view==='quiz'&&session?.mode==='exam'&&session.deadline){tickTimer();if(session)timerHandle=setInterval(tickTimer,1000);}}
function pauseSession(){if(session&&!result){saved.session=session;saved._sync.sessionAt=Date.now();save();}stopTimer();}
function setSubject(id){if(!QUIZ_DATA[id])return false;cancelSpeech();pauseSession();currentSubject=id;activeSubject=id;activeQuestions=QUIZ_DATA[id];CORE=activeQuestions.filter(q=>!q.extra);CHAPTERS=QUIZ_CHAPTERS[id];saved=progressRoot[id];ensurePrefs();session=null;result=null;chapter=0;goal=8;bankOrigin='all';return true;}
function openSubject(id){if(setSubject(id))go('home');}
function go(v){cancelSpeech();pauseSession();view=v;session=null;result=null;page=1;query='';topic='';onlyReview=false;includeExtra=false;if(v==='wrong'||v==='saved'){goal=8;chapter=0;bankOrigin='all';}render();window.scrollTo(0,0);}
function filtered(){const list=includeExtra&&view==='bank'?activeQuestions:CORE;const numeric=/^\d+$/.test(query.trim());return list.filter(q=>(!chapter||q.chapter===chapter)&&(!topic||q.topic===topic)&&(q.tier<=goal||q.extra)&&(!onlyReview||q.review)&&(bankOrigin==='all'||q.origin===bankOrigin)&&(view!=='wrong'||saved.progress[q.key]?.last===false&&isGradable(q))&&(view!=='saved'||saved.bookmarks.includes(q.key))&&(!query||(numeric?q.number===Number(query):normalize(q.question+' '+q.number+' '+q.key+' '+q.options.join(' ')).includes(normalize(query)))));}
function record(q,a){const old=saved.progress[q.key]||{attempts:0,correct:0};saved.progress[q.key]={attempts:old.attempts+1,correct:old.correct+(isCorrect(q,a)?1:0),last:isGradable(q)?isCorrect(q,a):null,lastAnswer:a,at:Date.now()};}
function chip(q,index=null,total=0){const source=q.origin==='practice'?'Bài tập '+q.practiceNumber:'Câu '+q.number,inQuiz=Number.isInteger(index)&&total>0;return `<span class="badge">${inQuiz?'Câu '+(index+1)+' / '+total:source+' · Chương '+q.chapter}</span>${inQuiz?`<span class="quiz-source-number">Câu gốc: ${esc(source.replace(/^Câu /,''))} · Chương ${q.chapter}</span>`:''}<span>Mức ${q.tier}${q.extra?' · Phụ lục':''}</span>${!isGradable(q)&&!q.extra?'<span class="badge amber">Không tính điểm</span>':q.review?'<span class="badge amber">Cần đối chiếu</span>':''}`;}

function bookmark(q){return `<button class="bookmark" data-bookmark="${q.key}" aria-pressed="${saved.bookmarks.includes(q.key)}" aria-label="Đánh dấu câu ${q.number}">${saved.bookmarks.includes(q.key)?'★ Đã lưu':'☆ Lưu câu'}</button>`;}
function feedback(q){return `<div class="explanation"><strong>GIẢI THÍCH & CÁCH NHỚ</strong><p>${esc(q.explanation)}</p>${q.note?`<div class="notice">${esc(q.note)}</div>`:''}${(q.sources||[]).map(s=>`<a class="source" target="_blank" rel="noopener" href="${esc(s.url)}">↗ ${esc(s.label)}</a>`).join('')}${q.sourceNote?`<p class="micro">${esc(q.sourceNote)}</p>`:''}</div>${q.review?`<div class="notice">${!isGradable(q)?'Câu chưa có đáp án duy nhất hợp lệ. Lựa chọn được lưu nhưng không tính đúng/sai hay điểm.':q.answers.length>1?'Chấp nhận '+answerLabel(q)+'. Chỉ cần chọn một phương án hợp lệ.':'Câu có lưu ý. Đáp án tham khảo cần đối chiếu cùng tài liệu giảng viên.'}</div>`:''}`;}
function item(q,review=null){const reviewing=review!==null&&typeof review==='object',answer=reviewing?review.answer:undefined,gradable=isGradable(q),correct=gradable&&isCorrect(q,answer),status=!gradable?'Cần đối chiếu':!answer?'Chưa chọn':correct?'Đã trả lời đúng':'Cần ôn lại';return `<article class="bankitem ${reviewing?'review-question':''}" ${reviewing?`data-review-key="${esc(q.key)}"`:''}><div class="meta">${chip(q)}${bookmark(q)}</div><h3 class="bank-question">${highlightText(q.question)}</h3>${reviewing?`<div class="review-comparison ${!gradable?'is-pending':correct?'is-correct':'is-wrong'}"><span class="review-outcome">${status}</span><div><span>Bạn chọn</span><strong>${answer?esc(choiceLabel(q,answer)):'Chưa chọn'}</strong></div><div><span>${gradable?'Đáp án tham khảo':'Trạng thái đáp án'}</span><strong>${gradable?esc(answerLabel(q)):'Chưa có đáp án duy nhất'}</strong></div></div>`:''}${mediaControls(q)}${hintBox(q)}<details class="bank-answer" ${reviewing?'open':''}><summary>${reviewing?'Đáp án & giải thích':'Xem đáp án & giải thích'}</summary><ol class="option-list">${q.options.map((o,i)=>{const letter='ABCD'[i],accepted=acceptedAnswers(q).includes(letter)&&(!reviewing||gradable),chosen=answer===letter;return `<li class="${accepted?'correct':''} ${reviewing&&chosen?'review-chosen '+(gradable&&!correct?'incorrect':''):''}"><span class="review-option-text">${q.labels[i]}. ${highlightText(o)}</span>${reviewing?`<span class="review-option-tags">${chosen?'<span class="review-tag chosen">Bạn chọn</span>':''}${accepted?'<span class="review-tag accepted">Đáp án tham khảo</span>':''}</span>`:''}</li>`;}).join('')}</ol>${feedback(q)}</details></article>`;}

function historyTargetCards(){return `<div class="target-grid">${[6,7,8].map(g=>`<button class="target ${goal===g?'selected':''}" data-goal="${g}" aria-pressed="${goal===g}"><span class="check">${goal===g?'✓':''}</span><div class="score">${g}<small> điểm</small></div><strong>${g===6?'Nắm nền tảng':g===7?'Hiểu & liên hệ':'Bao quát & phân biệt'}</strong><p>${g===6?'Nhân vật, sự kiện, tổ chức và các mốc cốt lõi.':g===7?'Thêm nguyên nhân, ý nghĩa, vai trò và quan hệ.':'Thêm câu phủ định, văn kiện và chi tiết dễ nhầm.'}</p><div class="count">${CORE.filter(q=>q.tier<=g).length} câu tích lũy ${g>6?'· gồm mức trước':''}</div></button>`).join('')}</div>`;}
function targetCards(){if(currentSubject==='history')return historyTargetCards();return `<div class="target-grid">${[6,7,8].map(g=>`<button class="target ${goal===g?'selected':''}" data-goal="${g}" aria-pressed="${goal===g}"><span class="check">${goal===g?'✓':''}</span><div class="score">${g}<small> điểm</small></div><strong>${g===6?'Nắm nền tảng':g===7?'Hiểu & vận dụng':'Bao quát & phân biệt'}</strong><p>${g===6?'Khái niệm, định nghĩa và công thức cốt lõi.':g===7?'Thêm liên hệ, ứng dụng và bài tập.':'Thêm chi tiết dễ nhầm và câu cần đối chiếu.'}</p><div class="count">${CORE.filter(q=>q.tier<=g).length} câu tích lũy</div></button>`).join('')}</div>`;}
function historyHome(){const seen=CORE.filter(q=>saved.progress[q.key]&&(saved.progress[q.key].lastAnswer||!('lastAnswer'in saved.progress[q.key]))).length,wrong=CORE.filter(q=>saved.progress[q.key]?.last===false).length,correct=CORE.filter(q=>saved.progress[q.key]?.last===true).length;return `<section class="hero"><div><div class="eyebrow">LỊCH SỬ ĐẢNG CỘNG SẢN VIỆT NAM</div><h1>Hiểu dòng lịch sử.<br>Vững từng câu hỏi.</h1><p>Một lộ trình ôn tập rõ ràng: chọn mục tiêu, học theo chương,<br>ghi nhớ từ khóa và quay lại những câu còn vướng.</p></div><div class="hero-art" aria-hidden="true"><div class="arch"></div><div class="book"><span class="star">★</span>LỊCH SỬ<br>ĐẢNG<small>1930 — 2021</small></div></div></section><section class="stats"><div class="stat"><label>Ngân hàng kiến thức</label><strong>362</strong><small>câu hỏi</small></div><div class="stat"><label>Đã trả lời</label><strong>${seen}</strong><small>/ 362 câu</small></div><div class="stat"><label>Đúng lần gần nhất</label><strong style="color:var(--green)">${correct}</strong><small>câu hỏi</small></div><div class="stat"><label>Cần ôn lại</label><strong style="color:var(--red)">${wrong}</strong><small>câu hỏi</small></div></section>${saved.session?'<div class="resumebox"><span>Bạn có một lượt luyện đang dở. Tiếp tục từ nơi đã dừng.</span><button class="btn green" id="resume">Tiếp tục học →</button></div>':''}<div class="sectionhead"><h2>Chọn mục tiêu của bạn</h2><p>Học chắc từng lớp kiến thức</p></div>${targetCards()}<p class="micro">Nhóm do tôi gợi ý để ưu tiên học, không phải dự đoán cấu trúc đề hoặc cam kết điểm. Mức 8 bao gồm toàn bộ 362 câu.</p><div class="sectionhead"><h2>Ôn theo từng chương</h2><button class="btn link" data-view="bank">Xem tất cả câu hỏi ↗</button></div><section class="chapters">${CHAPTERS.map(ch=>{const a=CORE.filter(q=>q.chapter===ch.id),s=a.filter(q=>saved.progress[q.key]&&(saved.progress[q.key].lastAnswer||!('lastAnswer'in saved.progress[q.key]))).length;return `<article class="chapter"><div class="chapter-top"><div class="index">CHƯƠNG 0${ch.id}<span>${ch.count} CÂU HỎI</span></div><h3>${ch.title}</h3><div class="period">${ch.period}</div></div><div class="chapter-bottom"><div class="progresslabel"><span>Tiến độ đã trả lời</span><span>${s}/${ch.count}</span></div><div class="meter"><i style="width:${s/ch.count*100}%"></i></div><button data-chapter="${ch.id}">Bắt đầu ôn chương ${ch.id}<span>→</span></button></div></article>`;}).join('')}</section><section class="studybox"><div><h3>20 câu hôm nay. Thêm một phần tự tin.</h3><p>Một lượt ngẫu nhiên theo mục tiêu ${goal} điểm · Giải thích ngay sau mỗi câu.</p></div><button class="btn primary" id="quick">Luyện nhanh 20 câu <span>→</span></button></section><div class="notice">Đáp án bám tài liệu bạn gửi. Có <b>25 câu cần đối chiếu</b> về cách hỏi, mốc hoặc đáp án; hãy đọc ghi chú trước khi học thuộc. Câu quảng bá website (chương 3, câu 135) được giữ ở phụ lục và không tính điểm. <a href="#" data-review-list> Xem các câu cần đối chiếu →</a></div>`;}
function home(){if(currentSubject==='history')return historyHome();const s=subjectStats(currentSubject),review=CORE.filter(q=>q.review).length,pending=CORE.filter(q=>!isGradable(q)).length;return `<button class="btn link" data-catalog>← Thư viện môn học</button><section class="unified-hero"><div><div class="eyebrow">GÓC ÔN TẬP / ${esc(subjectTitle())}</div><h1>Hiểu từng ý.<br>Vững từng câu.</h1><p>Cùng một cách học cho mọi môn: hiểu gợi ý, thử trả lời, nghe lại và luyện đúng chỗ còn vướng.</p></div><div class="unified-hero-actions"><button class="btn primary" id="quick">Luyện nhanh 20 câu →</button><button class="btn" data-exam-setup>Tự kiểm tra có tính giờ</button><button class="btn" data-view="bank">Mở ngân hàng câu hỏi</button></div></section><section class="stats"><div class="stat"><label>Ngân hàng kiến thức</label><strong>${s.total}</strong><small>${s.gradable} câu chấm được</small></div><div class="stat"><label>Đã trả lời</label><strong>${s.seen}</strong><small>/ ${s.total} câu</small></div><div class="stat"><label>Đúng lần gần nhất</label><strong style="color:var(--green)">${s.correct}</strong><small>câu hỏi</small></div><div class="stat"><label>Cần ôn lại</label><strong style="color:var(--red)">${s.wrong}</strong><small>câu hỏi</small></div></section>${saved.session?'<div class="resumebox"><span>Lượt ôn môn này đang dở. Thời gian thi vẫn chạy khi tạm rời.</span><button class="btn green" id="resume">Tiếp tục lượt ôn →</button></div>':''}<div class="sectionhead"><h2>Chọn lớp kiến thức</h2><p>Mức ưu tiên 6 → 7 → 8</p></div>${targetCards()}<p class="micro">Phân nhóm hỗ trợ học, không dự đoán điểm hoặc cấu trúc đề thi. Mức 8 bao gồm toàn bộ câu của môn.</p><div class="sectionhead"><h2>Ôn theo chương & chủ đề</h2></div><section class="chapters">${CHAPTERS.map(ch=>{const a=CORE.filter(q=>q.chapter===ch.id),seen=a.filter(q=>saved.progress[q.key]&&(saved.progress[q.key].lastAnswer||!('lastAnswer'in saved.progress[q.key]))).length;return `<article class="chapter"><div class="chapter-top"><div class="index">CHƯƠNG ${ch.id}<span>${a.length} CÂU HỎI</span></div><h3>${esc(ch.title)}</h3></div><div class="chapter-bottom"><div class="progresslabel"><span>Đã trả lời</span><span>${seen}/${a.length}</span></div><div class="meter"><i style="width:${a.length?seen/a.length*100:0}%"></i></div><button data-chapter="${ch.id}">Ôn chương ${ch.id}<span>→</span></button></div></article>`;}).join('')}</section><div class="notice">${currentSubject==='information'?'Giữ nguyên 151 câu PDF và thêm 48 bài tập tính toán (12 câu/chương). ':currentSubject==='ai'?'Giữ 115 câu gốc, gồm câu 50 có hai lựa chọn; PDF không có số 74. ':''}${review} câu có lưu ý; ${pending} câu chưa đủ căn cứ chấm. Những câu này vẫn có gợi ý, nguồn và giải thích. <button class="btn link" data-review-list>Xem câu cần đối chiếu →</button></div>${currentSubject!=='history'?`<div class="sectionhead"><h2>Đọc lại nền tảng</h2></div><div class="lesson-list">${LESSONS[currentSubject].map(l=>`<details class="lesson-card"><summary>${esc(l.title)}</summary><div class="lesson-body"><h3>${esc(l.lead)}</h3><p>${l.body}</p><div class="formula-box">${esc(l.formula)}</div><p>${esc(l.example)}</p><p>${esc(l.remember)}</p></div></details>`).join('')}</div>`:''}`;}
function filters(){const topics=[...new Set(CORE.filter(q=>!chapter||q.chapter===chapter).map(q=>q.topic))];return `<div class="filters"><div class="field"><label for="chapter">Chương / phần</label><select id="chapter"><option value="0">Tất cả các chương</option>${CHAPTERS.map(c=>`<option value="${c.id}" ${chapter===c.id?'selected':''}>${c.id} · ${esc(c.title)}</option>`).join('')}</select></div><div class="field"><label for="goal">Nhóm ôn tích lũy</label><select id="goal">${[6,7,8].map(g=>`<option value="${g}" ${goal===g?'selected':''}>Mức ${g}${g===8?' · toàn bộ':''}</option>`).join('')}</select></div><div class="field topicfield"><label for="topic">Chủ đề</label><select id="topic"><option value="">Tất cả chủ đề</option>${topics.map(t=>`<option ${t===topic?'selected':''} value="${esc(t)}">${esc(t)}</option>`).join('')}</select></div>${currentSubject==='information'?`<div class="field"><label for="bank-origin">Nguồn câu hỏi</label><select id="bank-origin"><option value="all" ${bankOrigin==='all'?'selected':''}>Tất cả · 199 câu</option><option value="pdf" ${bankOrigin==='pdf'?'selected':''}>Đề cương PDF · 151 câu</option><option value="practice" ${bankOrigin==='practice'?'selected':''}>Bài tập tính toán · 48 câu</option></select></div>`:''}<div class="field wide"><label for="search">Tìm số câu, nội dung hoặc mã câu</label><input type="search" id="search" placeholder="Số câu chính xác hoặc từ khóa…" value="esc-placeholder"></div><label class="filtercheck"><input id="review-filter" type="checkbox" ${onlyReview?'checked':''}> Chỉ câu cần đối chiếu</label>${currentSubject==='history'&&view==='bank'?`<label class="filtercheck"><input id="extra-filter" type="checkbox" ${includeExtra?'checked':''}> Hiện phụ lục nguồn tải</label>`:''}</div>`.replace('esc-placeholder',esc(query));}
function bank(){const a=filtered();return `<div class="pageintro"><div class="eyebrow">${esc(subjectTitle())}</div><h1>${view==='wrong'?'Luyện lại câu sai':view==='saved'?'Những câu đã đánh dấu':'Ngân hàng & luyện thi'}</h1><p>${view==='wrong'?'Câu có lần trả lời gần nhất chưa đúng. Luyện đúng để ra khỏi danh sách.':'Chọn phạm vi trước khi học hoặc tự kiểm tra. Các tính năng giống nhau ở cả ba môn.'}</p></div>${filters()}<div class="panel practice-setup"><div class="row"><div class="field"><label for="mode">Cách luyện</label><select id="mode"><option value="learn" ${mode==='learn'?'selected':''}>Học · giải thích ngay</option><option value="exam" ${mode==='exam'?'selected':''}>Tự kiểm tra · chấm cuối lượt</option></select></div><div class="field"><label for="size">Số câu mỗi lượt</label><select id="size">${[10,20,40,0].map(n=>`<option value="${n}" ${size===n?'selected':''}>${n?n+' câu':'Tất cả ('+a.filter(q=>!q.extra).length+' câu)'}</option>`).join('')}</select></div><div class="field"><label for="order">Thứ tự câu</label><select id="order"><option value="shuffle" ${order==='shuffle'?'selected':''}>Ngẫu nhiên</option><option value="original" ${order==='original'?'selected':''}>Theo thứ tự nguồn</option></select></div><div class="field"><label for="exam-minutes">Giới hạn thi (phút)</label><input id="exam-minutes" type="number" min="1" max="240" value="${examMinutes}"><small>Chỉ áp dụng ở chế độ tự kiểm tra</small></div><button class="btn primary" id="start" ${a.some(q=>!q.extra)?'':'disabled'} style="align-self:end">Bắt đầu luyện →</button></div><p class="micro" id="filter-summary">${a.filter(q=>!q.extra).length} câu phù hợp · ${a.filter(isGradable).length} câu tính điểm · Học: hiện giải thích; thi: giữ kín đến khi nộp.</p></div><div class="sectionhead"><h2 id="match-count">${a.length} câu phù hợp</h2><span class="micro">Gợi ý · Giọng đọc · Đánh dấu</span></div><div id="banklist">${bankList(a)}</div>`;}
function bankList(a){const pages=Math.ceil(a.length/20);page=Math.min(page,pages||1);return a.length?a.slice((page-1)*20,page*20).map(item).join('')+(pages>1?`<div class="pagination"><button class="btn" id="prev-page" ${page===1?'disabled':''}>← Trước</button><span>Trang ${page}/${pages}</span><button class="btn" id="next-page" ${page===pages?'disabled':''}>Sau →</button></div>`:''):'<div class="empty"><h3>Không có câu phù hợp</h3><p>Thử chương khác, mức 8 hoặc xóa bộ lọc.</p><button class="btn" id="reset-filters">Xóa bộ lọc</button></div>';}
function start(a){a=a.filter(q=>q.subject===currentSubject&&!q.extra);if(!a.length)return toast('Chưa có câu phù hợp.');if(saved.session&&!session&&!window.confirm('Thay lượt đang dở của môn này bằng lượt mới?'))return;cancelSpeech();stopTimer();const keys=(order==='shuffle'?shuffle(a):a).slice(0,size||a.length).map(q=>q.key),now=Date.now();session={subject:currentSubject,keys,index:0,answers:{},hints:{},hintsUsed:{},mode,created:now,deadline:mode==='exam'?now+examMinutes*60000:null};saved.session=session;saved._sync.sessionAt=now;result=null;view='quiz';save();render();window.scrollTo(0,0);}
function selectAnswer(letter){if(!session||result)return;const q=BYKEY[session.keys[session.index]];if(!q.options['ABCD'.indexOf(letter)]||session.mode==='learn'&&session.answers[q.key])return;if(session.mode==='exam'&&session.deadline&&remainingSeconds()===0)return finish(true);cancelSpeech();session.answers[q.key]=letter;playInteraction(session.mode==='learn'&&isGradable(q)?isCorrect(q,letter)?'correct':'wrong':'neutral');if(session.mode==='learn')record(q,letter);saved.session=session;saved._sync.sessionAt=Date.now();save();render();}
function quiz(){const q=BYKEY[session.keys[session.index]],answer=session.answers[q.key],show=session.mode==='learn'&&!!answer,answered=Object.keys(session.answers).length;return `<div class="row quiz-topline"><button class="btn link" id="pause">← Lưu & về tổng quan</button><span class="micro">${session.mode==='learn'?'CHẾ ĐỘ HỌC':'TỰ KIỂM TRA'} · ${answered}/${session.keys.length} đã chọn</span>${session.mode==='exam'&&session.deadline?`<span class="exam-timer" aria-label="Thời gian còn lại">◷ <b id="exam-clock">${timerText()}</b></span>`:''}</div><div class="meter"><i style="width:${answered/session.keys.length*100}%"></i></div><div class="quizlayout"><div class="quizcard"><div class="meta">${chip(q,session.index,session.keys.length)}${bookmark(q)}</div><p class="micro">${esc(q.topic)}</p><h2 tabindex="-1" id="question-title">${highlightText(q.question)}</h2>${mediaControls(q)}${q.review?`<p class="micro review-label">${isGradable(q)?'Có lưu ý; đọc phân tích sau khi trả lời hoặc nộp bài.':'Câu cần đối chiếu, không tính điểm.'}</p>`:''}${hintBox(q)}<div class="options">${q.options.map((o,i)=>{const l='ABCD'[i],cls=show?(isCorrect(q,l)?'correct':l===answer?isGradable(q)?'incorrect':'selected':''):l===answer?'selected':'';return `<button class="option ${cls}" data-answer="${l}" ${show?'disabled':''} aria-pressed="${l===answer}"><b>${q.labels[i]}</b><span>${highlightText(o)}</span></button>`;}).join('')}</div>${show?`<p class="micro answer-status">${!isGradable(q)?'Đã lưu lựa chọn · Không chấm đúng/sai.':isCorrect(q,answer)?'Bạn chọn đúng theo đáp án tham khảo.':'Bạn chọn '+choiceLabel(q,answer)+' · Đáp án tham khảo: '+answerLabel(q)+'.'}</p>${feedback(q)}`:''}<div class="quiznav"><button class="btn" id="back" ${session.index===0?'disabled':''}>← Câu trước</button>${session.index<session.keys.length-1?'<button class="btn primary" id="next">Câu tiếp theo →</button>':'<button class="btn primary" id="finish">Hoàn thành & xem kết quả</button>'}</div><p class="micro">Phím 1–4 / A–D để chọn · ← / → để chuyển câu.</p></div><aside class="quizaside"><h3>Hành trình lượt này</h3><p class="journey-numbering">Số ô là thứ tự câu trong lượt này.</p><div class="questiongrid">${session.keys.map((k,i)=>{const a=session.answers[k],q=BYKEY[k],cls=session.mode==='learn'&&a?(isGradable(q)?isCorrect(q,a)?'good':'bad':'answered'):a?'answered':'';return `<button data-jump="${i}" class="${cls} ${session.index===i?'current':''}" aria-label="Đến câu ${i+1}" title="Thứ tự ${i+1} · Câu gốc ${q.number}" ${session.index===i?'aria-current="step"':''}>${i+1}</button>`;}).join('')}</div><p>${session.mode==='learn'?'Xanh: đúng · Đỏ: cần ôn · Tím: chưa chấm.':'Ô có màu: đã chọn, chưa công bố đúng/sai.'}</p><button class="btn" id="finish" style="width:100%;margin-top:15px">Nộp lượt này</button><p>Thang 10 trên ${session.keys.filter(k=>isGradable(BYKEY[k])).length} câu chấm được. Câu chấm được nhưng bỏ trống tính 0. ${session.mode==='exam'?'Đồng hồ vẫn chạy khi rời trang.':''}</p></aside></div>`;}
function finish(forced=false){if(!session)return;const blank=session.keys.filter(k=>!session.answers[k]&&isGradable(BYKEY[k])).length;if(!forced&&blank&&!window.confirm(`Còn ${blank} câu tính điểm chưa chọn. Nộp lượt này?`))return;stopTimer();cancelSpeech();let right=0;for(const k of session.keys){const q=BYKEY[k],a=session.answers[k];if(isCorrect(q,a))right++;if(session.mode==='exam'||!a)record(q,a||'');}result={...session,right,expired:forced};saved.session=null;saved._sync.sessionAt=Date.now();session=null;view='result';resultFilter='wrong';save();render();window.scrollTo(0,0);if(forced)toast('Hết giờ — lượt thi đã được nộp tự động.');}
function resultPage(){const graded=result.keys.filter(k=>isGradable(BYKEY[k])),wrong=graded.filter(k=>!isCorrect(BYKEY[k],result.answers[k])),blank=graded.filter(k=>!result.answers[k]).length,pending=result.keys.filter(k=>!isGradable(BYKEY[k])),score=graded.length?(result.right/graded.length*10).toFixed(2):'—',list=resultFilter==='all'?result.keys:resultFilter==='pending'?pending:wrong;return `<div class="eyebrow">${esc(subjectTitle())} · ${result.expired?'HẾT GIỜ':'KẾT QUẢ LƯỢT ÔN'}</div><section class="resultcard"><h2>${result.expired?'Đã tự động nộp khi hết giờ.':'Bạn đã hoàn thành lượt này.'}</h2><div class="resultscore">${score}<small>${graded.length?' / 10':'Không có câu tính điểm'}</small></div><div class="resultsummary"><span>${result.right} đúng</span><span>${wrong.length-blank} sai</span><span>${blank} chưa chọn</span><span>${pending.length} không chấm</span><span>${Object.keys(result.hintsUsed||{}).length} dùng gợi ý</span></div><p class="micro">Điểm tính trên ${graded.length} câu chấm được, không gồm câu cần đối chiếu chưa có kết luận. Đây là điểm luyện tham khảo.</p><div class="row"><button class="btn primary" id="retry-wrong" ${wrong.length?'':'disabled'}>Luyện lại ${wrong.length} câu chưa đúng ↻</button><button class="btn" id="retry-all">Làm lại lượt này</button><button class="btn" data-view="home">Về tổng quan</button></div></section><div class="sectionhead"><h2>Xem lại & ghi nhớ</h2><select id="result-filter" aria-label="Lọc câu xem lại"><option value="wrong" ${resultFilter==='wrong'?'selected':''}>Sai / chưa chọn (${wrong.length})</option><option value="pending" ${resultFilter==='pending'?'selected':''}>Chưa chấm (${pending.length})</option><option value="all" ${resultFilter==='all'?'selected':''}>Tất cả (${result.keys.length})</option></select></div>${list.length?list.map(k=>item(BYKEY[k],{answer:result.answers[k]})).join(''):'<div class="empty"><h3>Không có câu trong nhóm này.</h3></div>'}`;}
function historyGuide(){return `<div class="pageintro"><div class="eyebrow">ÔN CÓ THỨ TỰ · HỌC CÓ ĐỐI CHIẾU</div><h1>Lộ trình 6 → 7 → 8 điểm</h1><p>Đây là cách phân nhóm ưu tiên học, không phải bản dự đoán đề thi. Hãy kết hợp với phạm vi giảng viên công bố.</p></div><div class="guidegrid"><div class="panel"><h3>01 · Chắc nền tảng trước</h3><p>Mức 6 gồm ${CORE.filter(q=>q.tier<=6).length} câu tích lũy. Học nhân vật, sự kiện, tổ chức, tên văn kiện, các mốc nổi bật.</p><ul><li>Học lần lượt chương 1 → 2 → 3.</li><li>Mỗi lượt 20 câu, đọc từ khóa sau khi chọn.</li><li>Làm lại câu sai hôm sau, tránh chỉ thuộc chữ đáp án.</li></ul></div><div class="panel"><h3>02 · Nối nguyên nhân với kết quả</h3><p>Mức 7 gồm ${CORE.filter(q=>q.tier<=7).length} câu tích lũy. Bổ sung ý nghĩa, vai trò, đặc điểm và quan hệ giữa các sự kiện.</p><ul><li>Tự nói một câu giải thích vì sao chọn đáp án.</li><li>So sánh Bắc / Nam, trước / sau, bước đầu / hoàn toàn.</li><li>Chuyển sang tự kiểm tra, chấm cuối lượt.</li></ul></div><div class="panel"><h3>03 · Phủ đủ bộ câu hỏi</h3><p>Mức 8 gồm toàn bộ 362 câu kiến thức. Thêm câu phủ định, chi tiết văn kiện và câu dễ nhầm.</p><ul><li>Gạch từ KHÔNG, CHỦ YẾU, QUYẾT ĐỊNH NHẤT.</li><li>Đọc đúng mốc văn kiện; câu chữ có thể thay đổi theo thời kỳ.</li><li>Tách câu đáng nghi để hỏi giảng viên.</li></ul></div><div class="panel"><h3>Nhịp học gợi ý mỗi ngày</h3><p>Khoảng 30–45 phút: 10 phút xem từ khóa và mốc, 15–20 phút luyện 20 câu, 5–15 phút làm lại câu sai.</p><ul><li>Mục tiêu tự luyện: nhiều lượt liên tiếp đạt khoảng 80% trở lên trên các chương.</li><li>Ưu tiên câu sai lặp lại thay vì làm mãi câu đã thuộc.</li><li>Tỷ lệ luyện đúng không bảo đảm điểm thi thật.</li></ul></div></div><div class="sectionhead"><h2>Các mốc làm trục ghi nhớ</h2></div><ul class="timeline"><li><strong>1911 → 1920 → 1925 → 1930</strong> Ra đi → tìm thấy con đường → Hội Thanh niên → thành lập Đảng.</li><li><strong>1930 → 1936–1939 → 1941 → 1945</strong> Cương lĩnh → dân chủ → hoàn chỉnh chuyển hướng → giành chính quyền.</li><li><strong>1946 → 1947 → 1950 → 1954</strong> Toàn quốc kháng chiến → Việt Bắc → Biên giới → Điện Biên Phủ & Giơnevơ.</li><li><strong>1960 → 1968 → 1973 → 1975</strong> Đồng Khởi & Đại hội III → Mậu Thân → Paris → thống nhất lãnh thổ.</li><li><strong>1976 → 1986 → 1991 → 2001 → 2011</strong> Thống nhất nhà nước → đổi mới → Cương lĩnh → mô hình kinh tế → bổ sung Cương lĩnh.</li></ul><div class="panel"><h3>Nguồn, cách chấm & những chỗ cần lưu ý</h3><p>Giữ nguyên 363 câu, 4 phương án và khóa đáp án từ tệp bạn gửi, với một sửa định dạng: chương 1 câu 81 thiếu nhãn D, nên thêm D cho dòng “Tổng khởi nghĩa giành chính quyền”. Chương 3 câu 135 quảng bá nơi tải tài liệu, được giữ ở phụ lục và không đưa vào lượt luyện có điểm.</p><p style="margin-top:12px">25 câu được gắn nhãn cần đối chiếu do phát hiện vấn đề cách hỏi, câu chữ hoặc đáp án. Các ghi chú là hỗ trợ học; chưa phải thẩm định toàn bộ bộ đề. Quiz giữ khóa nguồn để bạn so sánh với tài liệu giảng viên, kể cả câu đang có nghi vấn.</p><p style="margin-top:12px">Chương 3 câu 120: Cương lĩnh 2011 dùng từ “khuyến khích phát triển” với kinh tế có vốn đầu tư nước ngoài. Không nên suy ra từ đáp án D rằng chủ trương phủ nhận loại hình kinh tế này. <a target="_blank" rel="noopener" href="https://tulieuvankien.dangcongsan.vn/ban-chap-hanh-trung-uong-dang/dai-hoi-dang/lan-thu-xi/cuong-linh-xay-dung-dat-nuoc-trong-thoi-ky-qua-do-len-chu-nghia-xa-hoi-bo-sung-phat-trien-nam-2011-1528">Đọc nguyên văn Cương lĩnh 2011 ↗</a></p><button class="btn" data-review-list style="margin-top:17px">Xem 25 câu cần đối chiếu →</button></div><div class="panel"><h3>Giữ lại tiến độ học</h3><p>Tiến độ lưu ở trình duyệt này, không tự đồng bộ giữa các thiết bị. Xuất bản sao để mang sang máy khác hoặc tránh mất dữ liệu khi xóa bộ nhớ trình duyệt.</p><div class="row" style="margin-top:15px"><button class="btn" id="export">Xuất tiến độ</button><button class="btn" id="import">Nhập tiến độ</button><button class="btn" id="reset-progress">Đặt lại tiến độ</button><input id="import-file" type="file" accept="application/json,.json" hidden></div></div>`;}
function guide(){if(currentSubject==='history')return historyGuide();return `<div class="pageintro"><div class="eyebrow">${esc(subjectTitle())}</div><h1>Học có hướng, nhớ có cách.</h1><p>Mức 6: nền tảng · Mức 7: vận dụng · Mức 8: bao quát. Không cam kết điểm thi.</p></div><div class="guidegrid"><div class="panel"><h3>Học rồi tự kiểm tra</h3><p>Luyện nhanh 20 câu để xem giải thích ngay. Chọn chế độ tự kiểm tra để làm bài có tính giờ, đổi đáp án và nhảy câu. Hết giờ tự nộp; có thể tiếp tục lượt đang dở.</p></div><div class="panel"><h3>Ôn đúng phần còn vướng</h3><p>Dùng câu sai, đánh dấu và bộ lọc chủ đề riêng từng môn. Gợi ý, đọc câu hỏi, tốc độ giọng đọc và âm thanh có ở tất cả các môn.</p></div><div class="panel"><h3>Đọc kỹ nguồn & lưu ý</h3><p>Câu có nhiều lựa chọn đúng chấp nhận một phương án hợp lệ. Câu thiếu căn cứ không tính điểm. Nhóm mức và chương ở AI/Truyền tin do trợ lý phân loại để hỗ trợ học.</p><button class="btn" data-review-list>Xem câu cần đối chiếu</button></div><div class="panel"><h3>Sao lưu cả ba môn</h3><p>Tiến độ được tách theo môn. Có thể xuất tệp trước khi xóa dữ liệu trình duyệt. Đồng bộ tài khoản chỉ hoạt động khi API được cấu hình.</p><div class="row"><button class="btn" id="export">Xuất tiến độ</button><button class="btn" id="import">Nhập tiến độ</button><button class="btn" id="reset-progress">Đặt lại môn hiện tại</button><input id="import-file" type="file" accept="application/json,.json" hidden></div></div></div>`;}
function render(){window.KienJourney?.capture();stopTimer();$('#main').innerHTML=view==='catalog'?catalogPage():view==='home'?home():view==='quiz'&&session?quiz():view==='result'&&result?resultPage():view==='guide'?guide():bank();updateNav();academyShell();window.KienUI?.afterRender();window.KienChoices?.refresh();window.KienJourney?.restore(view==='quiz'?session:null);armTimer();}
function resume(){const s=saved.session;if(!s||!s.keys.every(k=>BYKEY[k]?.subject===currentSubject))return toast('Không có lượt đang dở hợp lệ ở môn này.');session=s;view='quiz';result=null;render();window.scrollTo(0,0);}
function moveQuestion(index){if(!session||index<0||index>=session.keys.length)return;cancelSpeech();session.index=index;saved.session=session;saved._sync.sessionAt=Date.now();save();render();$('#question-title')?.focus();}
function toggleBookmark(k){if(BYKEY[k]?.subject!==currentSubject)return;const i=saved.bookmarks.indexOf(k);if(i>=0)saved.bookmarks.splice(i,1);else saved.bookmarks.push(k);saved._sync.bookmarks[k]={value:i<0,at:Date.now()};save();}
document.addEventListener('click',e=>{const t=e.target.closest('button,a');if(!t||t.disabled)return;const d=t.dataset;if(d.view){e.preventDefault();go(d.view);return;}if('examSetup'in d){go('bank');mode='exam';render();return;}if(d.goal){goal=Number(d.goal);render();return;}if(d.chapter){chapter=Number(d.chapter);topic='';query='';view='bank';page=1;render();window.scrollTo(0,0);return;}if('reviewList'in d){e.preventDefault();go('bank');goal=8;chapter=0;onlyReview=true;render();return;}if(d.bookmark){toggleBookmark(d.bookmark);t.textContent=saved.bookmarks.includes(d.bookmark)?'★ Đã lưu':'☆ Lưu câu';t.setAttribute('aria-pressed',String(saved.bookmarks.includes(d.bookmark)));return;}if(d.tts){speakQuestion(d.tts);return;}if('sound'in d){saved.prefs.sound=!saved.prefs.sound;saved._sync.prefsAt=Date.now();save();document.querySelectorAll('[data-sound]').forEach(b=>{b.textContent=saved.prefs.sound?'♪ Âm thanh: Bật':'♪ Âm thanh: Tắt';b.setAttribute('aria-pressed',String(saved.prefs.sound));});playInteraction();return;}if(d.hint){const panel=document.getElementById(t.getAttribute('aria-controls'));if(!panel)return;const open=t.getAttribute('aria-expanded')!=='true';t.setAttribute('aria-expanded',String(open));t.innerHTML='✦ '+(open?'Ẩn gợi ý':'Gợi ý');panel.hidden=!open;if(session){session.hints||={};session.hintsUsed||={};session.hints[d.hint]=open;if(open)session.hintsUsed[d.hint]=true;saved._sync.sessionAt=Date.now();save();}return;}if(d.answer){selectAnswer(d.answer);return;}if(d.jump!==undefined){moveQuestion(Number(d.jump));return;}
 switch(t.id){case'quick':chapter=0;topic='';query='';onlyReview=false;includeExtra=false;bankOrigin='all';view='bank';size=20;mode='learn';order='shuffle';start(filtered());break;case'start':start(filtered());break;case'resume':resume();break;case'pause':go('home');break;case'back':moveQuestion(session.index-1);break;case'next':moveQuestion(session.index+1);break;case'finish':finish();break;case'prev-page':case'next-page':page+=t.id==='next-page'?1:-1;render();$('#match-count')?.scrollIntoView({block:'center'});break;case'reset-filters':chapter=0;goal=8;topic='';query='';onlyReview=false;bankOrigin='all';includeExtra=false;page=1;render();break;case'retry-wrong':{const list=result.keys.filter(k=>isGradable(BYKEY[k])&&!isCorrect(BYKEY[k],result.answers[k])).map(k=>BYKEY[k]);size=0;mode='learn';start(list);break;}case'retry-all':{const list=result.keys.map(k=>BYKEY[k]);size=0;mode=result.mode;start(list);break;}case'export':{const url=URL.createObjectURL(new Blob([JSON.stringify(progressRoot,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='kienhoc-tien-do-3-mon.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}case'import':$('#import-file').click();break;case'reset-progress':if(window.confirm('Đặt lại tiến độ, dấu sao và lượt đang dở của '+subjectTitle()+'? Các môn khác được giữ nguyên.')){const prefs=saved.prefs;saved=QuizStore.empty();saved.prefs=prefs;saved._sync.resetAt=Date.now();saved._sync.sessionAt=Date.now();save();render();}break;}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;page=1;const a=filtered();$('#banklist').innerHTML=bankList(a);$('#match-count').textContent=a.length+' câu phù hợp';$('#start').disabled=!a.some(q=>!q.extra);const allOption=$('#size option[value="0"]');if(allOption)allOption.textContent='Tất cả ('+a.filter(q=>!q.extra).length+' câu)';$('#filter-summary').textContent=a.filter(q=>!q.extra).length+' câu phù hợp · '+a.filter(isGradable).length+' câu tính điểm';window.KienPolish?.refreshAnswers();window.KienChoices?.refresh();}if(e.target.matches?.('[data-speech-rate]'))document.querySelectorAll('[data-speech-rate-output]').forEach(x=>x.textContent=Number(e.target.value).toFixed(1)+'×');});
document.addEventListener('change',async e=>{const t=e.target;if(t.matches?.('[data-speech-rate]')){saved.prefs.speechRate=Math.min(1.5,Math.max(.6,Number(t.value)||.9));saved._sync.prefsAt=Date.now();save();cancelSpeech();document.querySelectorAll('[data-speech-rate]').forEach(x=>x.value=saved.prefs.speechRate);document.querySelectorAll('[data-speech-rate-output]').forEach(x=>x.textContent=saved.prefs.speechRate.toFixed(1)+'×');return;}switch(t.id){case'chapter':chapter=Number(t.value);topic='';page=1;render();break;case'goal':goal=Number(t.value);page=1;render();break;case'topic':topic=t.value;page=1;render();break;case'bank-origin':bankOrigin=t.value;page=1;render();break;case'review-filter':onlyReview=t.checked;page=1;render();break;case'extra-filter':includeExtra=t.checked;page=1;render();break;case'mode':mode=t.value;break;case'size':size=Number(t.value);break;case'order':order=t.value;break;case'exam-minutes':examMinutes=Math.min(240,Math.max(1,Math.round(Number(t.value)||20)));t.value=examMinutes;break;case'result-filter':resultFilter=t.value;render();break;case'import-file':{const f=t.files[0];if(!f)return;try{if(f.size>2000000)throw Error();const d=JSON.parse(await f.text());if(!QuizStore.validBackup(d))throw Error();if(window.confirm('Thay tiến độ bằng bản sao đã chọn? Bản cũ chỉ thay môn Lịch sử Đảng.')){if(d.version===2){for(const id of Object.keys(QUIZ_DATA))progressRoot[id]=QuizStore.importState(d[id],id);}else progressRoot.history=QuizStore.importState(QuizStore.legacyHistory(d),'history');saved=progressRoot[currentSubject];ensurePrefs();save();render();toast('Đã nhập tiến độ.');}}catch{toast('Tệp tiến độ không hợp lệ.');}break;}}});
document.addEventListener('keydown',e=>{if(e.target.closest?.('dialog[open]')||view!=='quiz'||!session||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;const a=({'1':'A','2':'B','3':'C','4':'D'})[e.key]||(/^[a-d]$/i.test(e.key)?e.key.toUpperCase():null);if(a){e.preventDefault();selectAnswer(a);}if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();moveQuestion(session.index+(e.key==='ArrowRight'?1:-1));}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)tickTimer();});
window.addEventListener?.('pagehide',()=>{if(session)save();});
// An active local quiz retains its UI during cloud merges; account switching clears it.
document.addEventListener('kien-cloud-progress',e=>{const active=view==='quiz'&&session;if(e.detail.switched){session=null;result=null;view='catalog';}if(e.detail.data.subjects){const incoming=e.detail.data.subjects;for(const id of Object.keys(QUIZ_DATA))progressRoot[id]=QuizStore.clean(incoming[id],id);}else if(e.detail.switched)progressRoot=QuizStore.root();else progressRoot.history=QuizStore.legacyHistory(e.detail.data);saved=progressRoot[currentSubject];ensurePrefs();if(active&&!e.detail.switched)saved.session=session;try{QuizStore.persist(progressRoot);}catch{}if(view==='quiz')updateNav();else render();});
ensurePrefs();try{QuizStore.persist(progressRoot);}catch{}render();if(window.KienBoot)window.KienBoot.ready();else{document.querySelectorAll('[data-app-shell]').forEach(el=>el.hidden=false);$('#app-boot').hidden=true;}
